<?php
declare(strict_types=1);requireRole('admin');require_once __DIR__.'/../../config/database.php';$activePage='central-stock';$rows=[];$error='';
try{$rows=database()->query("SELECT i.item_name,COALESCE(c.name,i.category) category,i.variety,i.quantity,COUNT(r.id) receipt_count,COALESCE(SUM(r.paid_amount),0) paid,COALESCE(SUM(r.balance_amount),0) balance FROM inventory_items i LEFT JOIN item_categories c ON c.id=i.category_id LEFT JOIN stock_receipts r ON r.item_id=i.id GROUP BY i.id,i.item_name,c.name,i.category,i.variety,i.quantity ORDER BY i.item_name,i.variety")->fetchAll();}catch(PDOException $e){error_log($e->getMessage());$error='Unable to load central stock.';}
function centralPaymentStatus(array $row):string{if((int)$row['receipt_count']===0)return 'No Receipts';if((float)$row['balance']<=0)return 'Fully Paid';if((float)$row['paid']<=0)return 'Unpaid';return 'Partially Paid';}
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Central Stock | WIDMS</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="assets/css/admin-dashboard.css" rel="stylesheet"></head><body><?php require __DIR__.'/../../includes/admin-sidebar.php';?><div class="admin-shell"><header class="topbar"><div class="d-flex align-items-center gap-3"><button class="menu-button" id="menu-button">&#9776;</button><h1>Central Stock</h1></div></header><main class="dashboard-content admin-operation-page"><?php if($error):?><div class="alert alert-danger"><?=$error?></div><?php endif;?><section class="admin-data-card"><div class="admin-data-header"><h2>Central Stock Inventory</h2></div><div class="admin-data-table-wrap"><table class="admin-data-table central-stock-table"><thead><tr><th>Item</th><th>Category</th><th>Variety</th><th>In Stock</th><th>Payment Status</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="5" class="admin-empty-row">No central stock items available.</td></tr><?php else:foreach($rows as $row):?><tr><td><strong><?=htmlspecialchars($row['item_name'],ENT_QUOTES,'UTF-8')?></strong></td><td><?=htmlspecialchars($row['category'],ENT_QUOTES,'UTF-8')?></td><td><?=htmlspecialchars($row['variety']?:'Standard',ENT_QUOTES,'UTF-8')?></td><td><strong><?=(int)$row['quantity']?></strong></td><td><?=centralPaymentStatus($row)?></td></tr><?php endforeach;endif;?></tbody></table></div><p class="admin-table-note">Stock availability and supplier payment status are tracked independently.</p></section></main></div><script src="assets/js/admin-dashboard.js"></script></body></html>
